// PT: Um laço que roda n vezes faz n passos: Θ(n).
for (let i = 0; i < n; i++) work();

// PT: Cada par (i, j) com i < j é visitado uma vez: n(n-1)/2 vezes, logo Θ(n²).
// Para n = 10 são 10 * 9 / 2 = 45 vezes.
for (let i = 0; i < n; i++)
	for (let j = i + 1; j < n; j++) work();

// PT: i dobra: 1, 2, 4, 8... só cerca de log2(n) iterações: Θ(log n).
for (let i = 1; i < n; i *= 2) work();

// PT: O externo dobra i, o interno roda i vezes: 1 + 2 + 4 + ... + n é cerca de 2n: Θ(n).
for (let i = 1; i < n; i *= 2)
	for (let j = 0; j < i; j++) work();

// PT: O interno pula de i em i: n/1 + n/2 + n/3 + ... é cerca de n log n: Θ(n log n).
for (let i = 1; i <= n; i++)
	for (let j = 0; j < n; j += i) work();

// PT: Invariante: quando o teste i < n roda, s é a soma de a[0..i-1].
// Início: i = 0, s = 0 (soma vazia). Manutenção: somar a[i] dá a soma de a[0..i].
// Fim: i = n, então s é a soma do vetor inteiro.
let s = 0;
for (let i = 0; i < a.length; i++) s += a[i];

// PT: Cada chamada espera a próxima, então n quadros se empilham: espaço O(n).
// (Sem otimização de chamada em cauda, que a maioria das linguagens não garante.)
function sum(n: number): number {
	if (n === 0) return 0;
	return n + sum(n - 1);
}
